describe('JavaScript Confirm Dialog', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
  });

  it('should show "You clicked: Ok" when confirming the dialog', () => {
    cy.window().then((win) => {
      cy.stub(win, 'confirm').returns(true);
    });

    cy.contains('button', 'Click for JS Confirm').click();

    cy.get('#result').should('contain', 'You clicked: Ok');
  });

  it('should show "You clicked: Cancel" when dismissing the dialog', () => {
    cy.window().then((win) => {
      cy.stub(win, 'confirm').returns(false);
    });

    cy.contains('button', 'Click for JS Confirm').click();

    cy.get('#result').should('contain', 'You clicked: Cancel');
  });

  it('should handle multiple confirm dialogs with different responses', () => {
    cy.window().then((win) => {
      cy.stub(win, 'confirm').returns(true);
    });

    cy.contains('button', 'Click for JS Confirm').click();
    cy.get('#result').should('contain', 'You clicked: Ok');

    cy.window().then((win) => {
      win.confirm.restore();
      cy.stub(win, 'confirm').returns(false);
    });

    cy.contains('button', 'Click for JS Confirm').click();
    cy.get('#result').should('contain', 'You clicked: Cancel');
  });

  it('should verify the button exists and is clickable', () => {
    cy.contains('button', 'Click for JS Confirm')
      .should('be.visible')
      .should('be.enabled');
  });
});
